ferramentas('14', 'Psicologia do Desenvolvimento: Infância e Adolescência', '04', [
  {titulo:'Qual fase psicossexual? (Freud)', sub:'Leia a situação e identifique a fase do desenvolvimento, segundo o slide de psicanálise.', opcoes:['Oral', 'Anal', 'Fálica', 'Latência', 'Genital'], nota:'Situações fictícias, com base no slide "Sobre a Psicanálise".', cenarios:[
    {situacao:'Um bebê de 6 meses leva à boca tudo o que pega e se acalma ao mamar.', correta:'Oral', explicacao:'A boca é a zona erógena, foco da gratificação na amamentação.'},
    {situacao:'Uma criança de 2 anos e meio, no desfralde, ora segura, ora "libera" no momento que escolhe, e observa a reação dos pais.', correta:'Anal', explicacao:'O controle do esfíncter, retendo ou liberando, e o teste do poder dos pais marcam a fase anal.'},
    {situacao:'Um menino de 4 anos pergunta sem parar por que meninos e meninas são diferentes e diz que vai se casar com a mãe.', correta:'Fálica', explicacao:'Curiosidade pelos genitais e pelas diferenças, e o Complexo de Édipo: fase fálica.'},
    {situacao:'Uma menina de 8 anos está empolgada com a alfabetização, os trabalhos da escola e a turma de amigas.', correta:'Latência', explicacao:'A libido se volta para o aprender, a escola e as amizades.'},
    {situacao:'Um adolescente de 15 anos vive o primeiro namoro e revive, de outro jeito, questões da infância.', correta:'Genital', explicacao:'Na adolescência, os genitais voltam a ser a zona erógena, agora de forma consciente, com a passagem ao objeto sexual.'},
    {situacao:'Uma criança de 3 anos e meio quer saber de onde vêm os bebês e compara o próprio corpo com o do irmão.', correta:'Fálica', explicacao:'Curiosidade pelos órgãos genitais e muitas perguntas: fase fálica.'}]},
  {titulo:'Qual estágio de Wallon?', sub:'Leia a situação e identifique o estágio do desenvolvimento segundo Wallon.', opcoes:['Impulsivo-emocional', 'Sensório-motor e projetivo', 'Personalismo', 'Categorial', 'Puberdade e adolescência'], nota:'Os estágios alternam o predomínio da afetividade e da inteligência.', cenarios:[
    {situacao:'Um bebê de 7 meses se acalma no colo, com o embalo e o toque da mãe; se expressa chorando e se mexendo.', correta:'Impulsivo-emocional', explicacao:'Expressão pelo corpo e pelo toque, na fusão com o outro (0 a 1 ano).'},
    {situacao:'Uma criança de 2 anos explora cada gaveta da casa e começa a juntar palavras para nomear o que encontra.', correta:'Sensório-motor e projetivo', explicacao:'Exploração, atos motores e mentais, pensamento e linguagem (1 a 3 anos).'},
    {situacao:'Uma criança de 4 anos responde "não!" a tudo e quer fazer as coisas sozinha, mas fica aflita longe da família.', correta:'Personalismo', explicacao:'Autonomia × vínculo com a família (3 a 6 anos).'},
    {situacao:'Uma criança de 9 anos organiza conceitos, compara semelhanças e diferenças entre animais e diferencia bem o que pensa do que o colega pensa.', correta:'Categorial', explicacao:'Diferenciação nítida entre eu e outro e exploração de semelhanças e diferenças (6 a 11 anos).'},
    {situacao:'Um jovem de 13 anos se preocupa com o próprio corpo e se opõe às opiniões dos pais.', correta:'Puberdade e adolescência', explicacao:'Retorno ao eu corporal e ao eu psíquico, com oposição (a partir de 11 anos).'}]},
  {titulo:'Conceitos de Winnicott', sub:'Leia a situação e identifique o conceito de Winnicott que ela ilustra.', opcoes:['Holding', 'Handling', 'Objeto transicional', 'Falso self', 'Mãe suficientemente boa'], nota:'Com base no slide sobre Winnicott.', cenarios:[
    {situacao:'A mãe mantém uma rotina calma e previsível, que faz o bebê se sentir seguro e amparado.', correta:'Holding', explicacao:'Proporcionar um ambiente acolhedor e consistente.'},
    {situacao:'No banho, o pai toca o corpo do bebê com cuidado, ajudando-o a perceber os próprios contornos.', correta:'Handling', explicacao:'O manejo ajuda a formar as bordas do corpo e a personalização.'},
    {situacao:'A criança não dorme sem a fraldinha de pano que carrega para todo lado, e é ela quem decide quando largá-la.', correta:'Objeto transicional', explicacao:'Objeto conservado pela criança, que "representa" a mãe.'},
    {situacao:'Uma criança que viveu falhas graves de cuidado se torna "boazinha demais", sempre atendendo ao que os outros esperam.', correta:'Falso self', explicacao:'Não foi o ambiente que se adaptou a ela; foi ela que se adaptou ao ambiente.'},
    {situacao:'A mãe atende o bebê no tempo dele no início e, aos poucos, permite pequenas frustrações que ele consegue suportar.', correta:'Mãe suficientemente boa', explicacao:'Adaptação ativa às necessidades, com a passagem gradual da ilusão à desilusão.'}]},
  {titulo:'Qual luto da adolescência?', sub:'Leia a situação e identifique o luto, segundo Aberastury e Knobel.', opcoes:['Luto pelo corpo infantil', 'Luto pela identidade e papel infantil', 'Luto pelos pais da infância'], nota:'Os três lutos de "Adolescência normal".', cenarios:[
    {situacao:'Ana, 12 anos, odeia que o corpo esteja mudando "sozinho" e se sente sem controle sobre ele.', correta:'Luto pelo corpo infantil', explicacao:'Assistir passivamente às mudanças do corpo, com sentimento de impotência.'},
    {situacao:'Léo, 14 anos, não quer mais ser tratado como criança, mas também foge de qualquer responsabilidade de adulto.', correta:'Luto pela identidade e papel infantil', explicacao:'Não pode mais ser dependente como a criança, nem tem a maturidade adulta.'},
    {situacao:'Bia, 15 anos, queria que os pais resolvessem tudo na hora; como não resolvem, ela se fecha no quarto, pensativa.', correta:'Luto pelos pais da infância', explicacao:'A perda dos pais protetores idealizados leva à introspecção.'},
    {situacao:'Caio, 13 anos, diz que "pode tudo" e que nada de ruim vai acontecer com ele, enquanto o corpo muda rápido.', correta:'Luto pelo corpo infantil', explicacao:'O pensamento onipotente aparece como defesa contra a impotência diante do corpo.'},
    {situacao:'Duda, 16 anos, alterna entre pedir independência total e pedir que os pais façam tudo por ela.', correta:'Luto pelos pais da infância', explicacao:'A ambivalência entre dependência e independência marca esse luto.'}]},
  {titulo:'Que gênese é essa? (Vygotsky)', sub:'Leia a situação e identifique o campo da gênese estudado por Vygotsky.', opcoes:['Filogênese', 'Ontogênese', 'Sociogênese', 'Microgênese'], nota:'Os quatro campos da gênese, segundo o slide sobre Vygotsky.', cenarios:[
    {situacao:'O ser humano tem um cérebro plástico, que permite adaptar-se a circunstâncias muito diferentes.', correta:'Filogênese', explicacao:'A história da espécie: o que somos capazes de fazer como espécie.'},
    {situacao:'A trajetória de Pedro, do nascimento até hoje, com as experiências que formaram o desenvolvimento dele.', correta:'Ontogênese', explicacao:'A sequência de experiências do indivíduo dentro do caminho da espécie.'},
    {situacao:'Em uma cultura, as crianças cuidam dos irmãos menores aos 6 anos; em outra, isso só acontece muito mais tarde.', correta:'Sociogênese', explicacao:'A cultura organiza o desenvolvimento de formas diferentes.'},
    {situacao:'A história de como Júlia, em particular, aprendeu a ler: cada passo e cada dificuldade desse aprendizado.', correta:'Microgênese', explicacao:'O desenvolvimento de um aspecto específico, com uma história própria em cada sujeito.'}]}
]);

ferramentas('16', 'Filosofia', '06', [
  {titulo:'Quem pensou isso? (arché)', sub:'Leia o princípio proposto e identifique o pré-socrático.', opcoes:['Tales', 'Anaxímenes', 'Heráclito', 'Empédocles', 'Demócrito', 'Pitágoras', 'Anaximandro', 'Parmênides'], nota:'Com base no Percurso 1 de Filosofia.', cenarios:[
    {situacao:'Tudo o que existe vem da água, que sustenta o mundo.', correta:'Tales', explicacao:'Tales de Mileto, o primeiro materialista.'},
    {situacao:'O princípio é o ar, que muda por condensação e rarefação.', correta:'Anaxímenes', explicacao:'Princípio material: o ar.'},
    {situacao:'O elemento estruturante de toda a realidade é o fogo; a sabedoria é entender como o mundo funciona.', correta:'Heráclito', explicacao:'Heráclito de Éfeso.'},
    {situacao:'Tudo resulta das interações entre água, terra, fogo e ar.', correta:'Empédocles', explicacao:'Os quatro elementos.'},
    {situacao:'A realidade é ordenada por algo material tão pequeno que é invisível e indivisível.', correta:'Demócrito', explicacao:'O átomo, de Demócrito de Abdera.'},
    {situacao:'A ordem do mundo se explica pelos números.', correta:'Pitágoras', explicacao:'Princípio metafísico: os números.'},
    {situacao:'O princípio é o indeterminado, algo infinito e imortal.', correta:'Anaximandro', explicacao:'O ápeiron.'},
    {situacao:'Só pode existir qualquer coisa se o ser estiver por baixo dela.', correta:'Parmênides', explicacao:'Parmênides de Eléa e o Ser.'}]},
  {titulo:'Qual escola helenística?', sub:'Leia a atitude diante da vida e identifique a escola.', opcoes:['Estoicismo', 'Epicurismo', 'Ceticismo', 'Cinismo', 'Ecletismo'], nota:'Situações fictícias, com base no Percurso 2 e no slide do Encontro II.', cenarios:[
    {situacao:'Marta perdeu o emprego e diz: "Não vou me deixar abalar, nem pela tristeza nem pela euforia".', correta:'Estoicismo', explicacao:'Controle das paixões pela apatia: ética de resiliência.'},
    {situacao:'Rui prefere um jantar simples com amigos a uma festa cara: quer o prazer, mas pensado.', correta:'Epicurismo', explicacao:'Prazer racionalizado, valorizando o natural e o essencial.'},
    {situacao:'Diante de cada notícia, Lia diz: "Não dá para ter certeza de nada".', correta:'Ceticismo', explicacao:'A dúvida usada de forma radical.'},
    {situacao:'Davi abriu mão de quase tudo, ignora as convenções sociais e diz que livre é quem de nada depende.', correta:'Cinismo', explicacao:'Diógenes de Sinope: viver segundo as leis naturais.'},
    {situacao:'Para resolver um problema, Clara pega um pouco de cada teoria, mesmo que elas se contradigam.', correta:'Ecletismo', explicacao:'Cícero: conciliar teorias diversas.'}]},
  {titulo:'Que ídolo de Bacon?', sub:'Leia a situação e identifique o ídolo que atrapalha o conhecimento.', opcoes:['Ídolo da tribo', 'Ídolo da caverna', 'Ídolo do foro (mercado)', 'Ídolo do teatro'], nota:'Situações fictícias, com base no Percurso 3.', cenarios:[
    {situacao:'Pedro acha que a natureza "quer" algo, como se ela sentisse e pensasse como as pessoas.', correta:'Ídolo da tribo', explicacao:'Tomar o modo humano de perceber como se fosse o do universo.'},
    {situacao:'Ana só aceita o que confirma as experiências da própria vida e descarta o resto.', correta:'Ídolo da caverna', explicacao:'A caverna que cada um constrói para si.'},
    {situacao:'Uma palavra carregada de preconceito numa manchete faz todo mundo julgar o caso antes de conhecê-lo.', correta:'Ídolo do foro (mercado)', explicacao:'O poder das palavras de distorcer a realidade.'},
    {situacao:'Um grupo aceita tudo o que seu líder diz, só porque é ele quem diz.', correta:'Ídolo do teatro', explicacao:'Sistemas e ideologias que se dizem donos da verdade por autoridade.'}]},
  {titulo:'Quem disse isso?', sub:'Leia a ideia e identifique o filósofo.', opcoes:['Sócrates', 'Platão', 'Aristóteles', 'Agostinho', 'Tomás de Aquino', 'Ockham', 'Descartes', 'Kant', 'Hobbes', 'Rousseau', 'Sartre', 'Bauman'], nota:'Ideias em paráfrase, com base nos Percursos 1 a 4.', cenarios:[
    {situacao:'A verdade existe, e o diálogo ajuda a trazê-la à luz, como uma parteira.', correta:'Sócrates', explicacao:'A maiêutica.'},
    {situacao:'Os sentidos nos mostram sombras; o conhecimento verdadeiro está no mundo das ideias.', correta:'Platão', explicacao:'Mito da Caverna, A República, livro VII.'},
    {situacao:'A virtude é o hábito de escolher o justo meio.', correta:'Aristóteles', explicacao:'Ética da eudaimonia.'},
    {situacao:'Creio para compreender, compreendo para crer.', correta:'Agostinho', explicacao:'Primazia da fé; doutrina da iluminação.'},
    {situacao:'Podemos chegar a Deus pela razão, por cinco vias.', correta:'Tomás de Aquino', explicacao:'Suma Teológica.'},
    {situacao:'Entre várias explicações, prefira a mais simples.', correta:'Ockham', explicacao:'Navalha de Ockham.'},
    {situacao:'Penso, logo existo.', correta:'Descartes', explicacao:'O cogito, primeira certeza da dúvida metódica.'},
    {situacao:'O conhecimento começa com a experiência, mas nem todo ele se origina dela.', correta:'Kant', explicacao:'Crítica da Razão Pura.'},
    {situacao:'Sem um poder absoluto, a vida seria violência contínua.', correta:'Hobbes', explicacao:'Leviatã e o estado de natureza.'},
    {situacao:'O homem nasce bom e a sociedade o corrompe.', correta:'Rousseau', explicacao:'O Contrato Social.'},
    {situacao:'A existência precede a essência.', correta:'Sartre', explicacao:'Existencialismo.'},
    {situacao:'Vivemos num mundo líquido, numa sociedade de consumidores.', correta:'Bauman', explicacao:'Modernidade líquida.'}]}
]);
ferramentas('13', 'Introdução à Psicologia', '03', [
  {titulo:'Quem descobriu o quê?', sub:'Leia a descoberta e identifique o pesquisador.', opcoes:['Müller', 'Flourens', 'Broca', 'Fritsch e Hitzig', 'Bessel', 'Helmholtz', 'Weber', 'Fechner'], nota:'Com base em Schultz e Schultz e nos slides da Aula 02.', cenarios:[
    {situacao:'Cada nervo sensorial, quando estimulado, produz sempre a sua sensação característica.', correta:'Müller', explicacao:'Teoria das energias específicas dos nervos.'},
    {situacao:'Destruiu partes do cérebro e da medula de animais e observou as consequências.', correta:'Flourens', explicacao:'Método da extirpação.'},
    {situacao:'Na autópsia de um homem que não falava, achou uma lesão na terceira convolução frontal.', correta:'Broca', explicacao:'Método clínico, 1861.'},
    {situacao:'Estimularam o córtex com correntes elétricas fracas e obtiveram respostas motoras.', correta:'Fritsch e Hitzig', explicacao:'Estimulação elétrica, 1870.'},
    {situacao:'Mostrou que as diferenças entre astrônomos ao registrar a passagem das estrelas eram sistemáticas.', correta:'Bessel', explicacao:'A equação pessoal.'},
    {situacao:'Fez a primeira medida da velocidade do impulso nervoso.', correta:'Helmholtz', explicacao:'Antes, pensava-se que o impulso fosse instantâneo.'},
    {situacao:'Mediu a menor distância entre duas pontas na pele que ainda são sentidas como duas.', correta:'Weber', explicacao:'Limiar de dois pontos.'},
    {situacao:'Formulou que a sensação cresce com o logaritmo da intensidade do estímulo.', correta:'Fechner', explicacao:'S = k log R, Elementos de Psicofísica (1860).'}]},
  {titulo:'Estruturalismo ou funcionalismo?', sub:'Leia a afirmação e identifique a escola.', opcoes:['Estruturalismo', 'Funcionalismo'], nota:'Titchener de um lado; James, Dewey, Angell, Thorndike e Woodworth do outro.', cenarios:[
    {situacao:'A psicologia deve descobrir do que a consciência é feita, seus elementos.', correta:'Estruturalismo', explicacao:'Análise da consciência em partes.'},
    {situacao:'A pergunta é para que serve a consciência na adaptação ao meio.', correta:'Funcionalismo', explicacao:'Influência de Darwin.'},
    {situacao:'Só observadores muito treinados podem relatar a experiência, sem cometer o erro de estímulo.', correta:'Estruturalismo', explicacao:'Introspecção experimental sistemática de Titchener.'},
    {situacao:'A consciência é um fluxo contínuo, como um rio, e não uma soma de pedaços.', correta:'Funcionalismo', explicacao:'William James.'},
    {situacao:'Crianças, animais e pessoas com transtornos também podem ser estudados.', correta:'Funcionalismo', explicacao:'Abre espaço à psicologia animal, do anormal e do desenvolvimento.'},
    {situacao:'A psicologia é uma ciência pura, sem preocupação com aplicações práticas.', correta:'Estruturalismo', explicacao:'Titchener estudava a mente generalizada.'},
    {situacao:'A psicologia deve ajudar a ajustar os indivíduos à escola e à fábrica.', correta:'Funcionalismo', explicacao:'Psicologia como ciência e técnica da adaptação.'}]},
  {titulo:'Que método psicofísico?', sub:'Leia o procedimento e identifique o método de Fechner.', opcoes:['Erro médio', 'Estímulos constantes', 'Limites'], nota:'Os três métodos psicofísicos, em situações fictícias.', cenarios:[
    {situacao:'O participante gira um botão até que a luz da direita pareça tão forte quanto a da esquerda.', correta:'Erro médio', explicacao:'Também chamado de método de ajuste.'},
    {situacao:'O pesquisador apresenta pesos fixos, em ordem aleatória, e pede para dizer se cada um é mais pesado que o padrão.', correta:'Estímulos constantes', explicacao:'Antes chamado de método dos casos certos e errados.'},
    {situacao:'Um som vai ficando mais alto aos poucos, até a pessoa dizer "agora ouvi".', correta:'Limites', explicacao:'Séries crescentes e decrescentes até o ponto de mudança.'},
    {situacao:'A pessoa ajusta o comprimento de uma linha até parecer igual à linha-padrão; calcula-se a média dos erros.', correta:'Erro médio', explicacao:'O participante controla o estímulo.'}]},
  {titulo:'Que empirista disse isso?', sub:'Leia a ideia e identifique o filósofo.', opcoes:['Locke', 'Berkeley', 'Hume', 'Hartley', 'James Mill', 'John Stuart Mill'], nota:'Com base em Schultz e Schultz, capítulo 2.', cenarios:[
    {situacao:'A mente nasce como papel em branco; as ideias vêm da sensação e da reflexão.', correta:'Locke', explicacao:'Ideias simples e complexas, qualidades primárias e secundárias.'},
    {situacao:'Só podemos ter certeza da percepção; o objeto é um acúmulo de sensações.', correta:'Berkeley', explicacao:'A percepção é a única realidade certa.'},
    {situacao:'As ideias se associam por semelhança e por contiguidade.', correta:'Hume', explicacao:'As duas leis de associação.'},
    {situacao:'A contiguidade, com a repetição, explica memória, raciocínio e emoção.', correta:'Hartley', explicacao:'Fundador formal do associacionismo.'},
    {situacao:'A mente é passiva, e a ideia complexa é a soma das simples.', correta:'James Mill', explicacao:'Mecanicismo levado ao extremo.'},
    {situacao:'Na química mental, o todo ganha qualidades que não estão nos elementos.', correta:'John Stuart Mill', explicacao:'Ele também defendeu uma ciência da psicologia.'}]}
]);
ferramentas('15', 'Psicologia e Artes', '05', [
  {titulo:'Catarse de quem?', sub:'Leia a ideia de catarse e identifique o autor.', opcoes:['Aristóteles', 'Freud', 'Vigotski'], nota:'Com base em Faria, Dias e Camargo (2019).', cenarios:[
    {situacao:'Ao se identificar com o herói da tragédia, o espectador sente piedade e terror, e as emoções se purificam.', correta:'Aristóteles', explicacao:'Relação ética e passiva do espectador com o personagem.'},
    {situacao:'A catarse é uma descarga da energia emocional acumulada.', correta:'Freud', explicacao:'Vigotski acha essa explicação incompleta.'},
    {situacao:'As emoções angustiantes se chocam com a forma da obra e se transformam no seu contrário.', correta:'Vigotski', explicacao:'Transformação qualitativa: a reação estética.'},
    {situacao:'Não existe espectador passivo: quem aprecia a obra realiza a sua própria catarse.', correta:'Vigotski', explicacao:'"O prazer artístico requer uma elevadíssima atividade do psiquismo."'},
    {situacao:'O efeito da tragédia é limpar as emoções suscitadas pelas ações do herói trágico.', correta:'Aristóteles', explicacao:'Purificação pela compaixão.'}]},
  {titulo:'Que conceito de Vigotski é esse?', sub:'Leia a situação e identifique o conceito da Psicologia da Arte.', opcoes:['Técnica social do sentimento', 'Duplicação do real', 'Emoções inteligentes', 'Forma supera o conteúdo', 'Mediação'], nota:'Situações fictícias, com base nos dois artigos da N1.', cenarios:[
    {situacao:'A tristeza que uma compositora sentiu sozinha vira uma canção que milhares de pessoas cantam juntas.', correta:'Técnica social do sentimento', explicacao:'O sentimento individual torna-se social pela obra.'},
    {situacao:'Lendo um romance, Rui sente o medo de um náufrago sem nunca ter estado no mar.', correta:'Duplicação do real', explicacao:'Vivência, por meio indireto, de emoções não cotidianas.'},
    {situacao:'Uma atriz vive a raiva da personagem com intensidade, mas sem cerrar os punhos de verdade.', correta:'Emoções inteligentes', explicacao:'Resolvem-se em imagens da fantasia.'},
    {situacao:'Um poema conta uma história triste num ritmo leve, e o leitor sai dele estranhamente tranquilo.', correta:'Forma supera o conteúdo', explicacao:'A contradição entre forma e conteúdo produz a catarse.'},
    {situacao:'Na visita ao museu, a professora explica o contexto da obra e a turma passa a enxergá-la de outro jeito.', correta:'Mediação', explicacao:'A apropriação da arte depende de mediadores, como o professor.'}]}
]);
